float hachage(vec3 position) {
    position = fract(position * vec3(.1031, .1030, .0973));
    position += dot(position, position.yzx + 33.33);
    return fract((position.x + position.y) * position.z);
}

float bruit(vec3 position) {
    vec3 partieEntiere = floor(position), partieFractionnaire = fract(position);
    partieFractionnaire = partieFractionnaire * partieFractionnaire * (3. - 2. * partieFractionnaire);
    return mix(mix(mix(hachage(partieEntiere), hachage(partieEntiere + vec3(1,0,0)), partieFractionnaire.x), 
                   mix(hachage(partieEntiere + vec3(0,1,0)), hachage(partieEntiere + vec3(1,1,0)), partieFractionnaire.x), partieFractionnaire.y),
               mix(mix(hachage(partieEntiere + vec3(0,0,1)), hachage(partieEntiere + vec3(1,0,1)), partieFractionnaire.x), 
                   mix(hachage(partieEntiere + vec3(0,1,1)), hachage(partieEntiere + vec3(1,1,1)), partieFractionnaire.x), partieFractionnaire.y), partieFractionnaire.z);
}

float bruitFractalO2(vec3 position) {
    float valeur = 0., amplitude = .5;
    mat3 matriceRotation = mat3(0, .8, .6, -.8, .36, -.48, -.6, -.48, .64);
    for (int i = 0; i < 2; i++) {
        valeur += amplitude * bruit(position);
        position = matriceRotation * position * 2.02;
        amplitude *= .5;
    }
    return valeur;
}

vec3 obtenirPositionObjet(int idx) {
    if (idx == 0) return vec3(0.0);
    if (idx == 1) return vec3(1.2 * cos(iTime * 2.2), 0.05 * sin(iTime * 2.2), 1.2 * sin(iTime * 2.2));
    if (idx == 2) return vec3(1.7 * cos(iTime * 1.6 + 0.8), -0.08 * cos(iTime * 1.6), 1.7 * sin(iTime * 1.6 + 0.8));
    if (idx == 3) return vec3(2.3 * cos(iTime * 1.2 + 2.0), 0.1 * sin(iTime * 1.2), 2.3 * sin(iTime * 1.2 + 2.0));
    if (idx == 4) return vec3(2.9 * cos(iTime * 0.9 + 3.5), -0.12 * cos(iTime * 0.9), 2.9 * sin(iTime * 0.9 + 3.5));
    if (idx == 5) return vec3(3.8 * cos(iTime * 0.6 + 1.2), 0.15 * sin(iTime * 0.6), 3.8 * sin(iTime * 0.6 + 1.2));
    if (idx == 6) return vec3(4.8 * cos(iTime * 0.4 + 4.5), -0.18 * cos(iTime * 0.4), 4.8 * sin(iTime * 0.4 + 4.5));
    if (idx == 7) return vec3(5.7 * cos(iTime * 0.3 + 2.8), 0.2 * sin(iTime * 0.3), 5.7 * sin(iTime * 0.3 + 2.8));
    return vec3(6.5 * cos(iTime * 0.2 + 5.2), -0.1 * cos(iTime * 0.2), 6.5 * sin(iTime * 0.2 + 5.2));
}

void mainImage(out vec4 couleurSortie, vec2 coordonneesPixel) {
    vec3 resolution = iResolution;

    float tempsSequence = iTime * 0.25;
    int indexSource = int(mod(tempsSequence, 9.0));
    int indexCible = int(mod(tempsSequence + 1.0, 9.0));
    float progressionRaw = fract(tempsSequence);
    float progression = smoothstep(0.0, 1.0, progressionRaw);

    vec3 posSource = obtenirPositionObjet(indexSource);
    vec3 posCible = obtenirPositionObjet(indexCible);

    vec3 cibleCamera = mix(posSource, posCible, progression);

    float decalageHauteur = mix(1.2, 3.5, sin(progression * 3.14159));
    float decalageDistance = mix(1.5, 4.5, sin(progression * 3.14159));

    vec3 positionCamera = cibleCamera + vec3(
        decalageDistance * cos(iTime * 0.4),
        decalageHauteur,
        decalageDistance * sin(iTime * 0.4)
    );

    vec3 directionAxeZ = normalize(cibleCamera - positionCamera);
    float angleRoulis = 0.25 * sin(iTime * 0.3);
    vec3 hautReference = vec3(sin(angleRoulis), cos(angleRoulis), 0.0);
    vec3 directionAxeX = normalize(cross(directionAxeZ, hautReference));
    vec3 directionAxeY = cross(directionAxeX, directionAxeZ);

    vec2 p = (coordonneesPixel + coordonneesPixel - resolution.xy) / resolution.y;
    vec3 directionRayon = normalize(p.x * directionAxeX + p.y * directionAxeY + 1.7 * directionAxeZ);

    couleurSortie = vec4(0);

    vec3 posMercure = obtenirPositionObjet(1);
    vec3 posVenus   = obtenirPositionObjet(2);
    vec3 posTerre   = obtenirPositionObjet(3);
    vec3 posMars    = obtenirPositionObjet(4);
    vec3 posJupiter = obtenirPositionObjet(5);
    vec3 posSaturne = obtenirPositionObjet(6);
    vec3 posUranus  = obtenirPositionObjet(7);
    vec3 posNeptune = obtenirPositionObjet(8);

    float distanceMarche = 0., pasMarche = 0.01;

    for (int i = 0; i < 64; i++) {
        vec3 position = positionCamera + distanceMarche * directionRayon;
        float rayon = length(position);

        vec2 posXZ = position.xz;
        float dMercure_2D = length(posXZ - posMercure.xz);
        float dVenus_2D   = length(posXZ - posVenus.xz);
        float dTerre_2D   = length(posXZ - posTerre.xz);
        float dMars_2D    = length(posXZ - posMars.xz);
        float dJupiter_2D = length(posXZ - posJupiter.xz);
        float dSaturne_2D = length(posXZ - posSaturne.xz);
        float dUranus_2D  = length(posXZ - posUranus.xz);
        float dNeptune_2D = length(posXZ - posNeptune.xz);

        float invRayon = 1. / max(rayon, .1);
        float valeurPotentiel = invRayon + 0.05 / max(dMercure_2D, .04) + 0.08 / max(dVenus_2D, .05)
                                         + 0.10 / max(dTerre_2D, .05)   + 0.07 / max(dMars_2D, .04)
                                         + 0.22 / max(dJupiter_2D, .07) + 0.18 / max(dSaturne_2D, .06)
                                         + 0.14 / max(dUranus_2D, .05)  + 0.13 / max(dNeptune_2D, .05);

        float dMercure = length(position - posMercure) - 0.05;
        float dVenus   = length(position - posVenus) - 0.08;
        float dTerre   = length(position - posTerre) - 0.09;
        float dMars    = length(position - posMars) - 0.06;
        float dJupiter = length(position - posJupiter) - 0.18;
        float dSaturne = length(position - posSaturne) - 0.14;
        float dUranus  = length(position - posUranus) - 0.11;
        float dNeptune = length(position - posNeptune) - 0.10;

        float distancePlanetes = min(dMercure, min(dVenus, min(dTerre, min(dMars, min(dJupiter, min(dSaturne, min(dUranus, dNeptune)))))));

        float effetFeu = (rayon < 1.5) ? bruit(position * 3. - vec3(0, iTime * 1.5, 0)) * 0.5 : 0.0;
        float distanceSoleil = rayon - 0.75 - effetFeu * 0.1;

        float distGrille = abs(position.y + valeurPotentiel - 1.);
        pasMarche = min(distGrille - .03, min(distanceSoleil, distancePlanetes));

        if (distanceSoleil < 0.005) {
            vec3 normale = normalize(position);
            vec3 couleurBruit = mix(vec3(1, .9, .2), vec3(1, .1, 0), bruitFractalO2(position * 4. + vec3(iTime * 0.5)));
            float fresnel = pow(1.0 - max(0.0, dot(-directionRayon, normale)), 2.5);
            couleurSortie.rgb += couleurBruit * 2.8 + vec3(1.0, 0.5, 0.1) * fresnel * 2.5;
            break;
        }

        if (distancePlanetes < 0.005) {
            vec3 normale = vec3(0.0);
            vec3 albedo = vec3(0.0);

            if (dMercure < 0.005) {
                normale = normalize(position - posMercure);
                albedo = vec3(.6, .5, .5) * (0.5 + 0.5 * bruit(position * 20.));
            } else if (dVenus < 0.005) {
                normale = normalize(position - posVenus);
                albedo = vec3(.9, .7, .3) * (0.7 + 0.3 * bruit(position * 8.));
            } else if (dTerre < 0.005) {
                normale = normalize(position - posTerre);
                albedo = vec3(.2, .5, .9) * (0.5 + 0.5 * bruit(position * 10.));
            } else if (dMars < 0.005) {
                normale = normalize(position - posMars);
                albedo = vec3(.8, .3, .1) * (0.6 + 0.4 * bruit(position * 15.));
            } else if (dJupiter < 0.005) {
                normale = normalize(position - posJupiter);
                albedo = vec3(.8, .6, .4) * (0.6 + 0.4 * sin(position.y * 35. + bruit(position * 5.) * 3.));
            } else if (dSaturne < 0.005) {
                normale = normalize(position - posSaturne);
                albedo = vec3(.9, .8, .5) * (0.7 + 0.3 * sin(position.y * 40.));
            } else if (dUranus < 0.005) {
                normale = normalize(position - posUranus);
                albedo = vec3(.4, .8, .8) * (0.8 + 0.2 * bruit(position * 6.));
            } else {
                normale = normalize(position - posNeptune);
                albedo = vec3(.2, .3, .9) * (0.7 + 0.3 * bruit(position * 8.));
            }

            vec3 dirLumiere = normalize(-position);
            float diff = max(dot(normale, dirLumiere), 0.15);
            vec3 reflet = reflect(directionRayon, normale);
            float spec = pow(max(dot(reflet, dirLumiere), 0.0), 32.0);

            couleurSortie.rgb += albedo * diff + vec3(1.0, 0.9, 0.7) * spec * 1.2;
            break;
        }

        vec2 grille = abs(fract(position.xz * 2. - .5) - .5);
        float facteurPlein = smoothstep(.04, .0, min(grille.x, grille.y)) * smoothstep(.15, .0, distGrille) * smoothstep(12., .5, rayon);

        float pasSecurise = max(abs(pasMarche), 0.001);
        vec3 couleurVolumique = mix(vec3(1, .4, .1), vec3(.15, .45, 1), clamp((rayon - 1.2) * 0.3, 0., 1.)) * (.0025 + .0006 / (pasSecurise * pasSecurise + .0015)) * exp(-rayon * .2);
        vec3 couleurGrille = vec3(0, .8, 1) * facteurPlein * 0.4;

        couleurSortie.rgb += couleurVolumique + couleurGrille;

        distanceMarche += max(pasMarche, 0.008);
    }

    vec3 couleurTonemapped = couleurSortie.rgb;
    couleurTonemapped = mix(couleurTonemapped, couleurTonemapped * couleurTonemapped * 0.5 + couleurTonemapped, 0.15);
    couleurSortie.rgb = pow(couleurTonemapped / (vec3(1.0) + couleurTonemapped * 0.75), vec3(0.4545));
}
